1	package clinical
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Grant 由内部使用者为一名接收方建立针对某患者的整类读取授权。
11	//
12	// 这是 [Store.GrantSelective] 的整类形式：范围由明确的“就诊 + 类别
13	// （诊断/医嘱）”组合构成，覆盖各就诊+类别下的全部已生效记录（含授权
14	// 建立后才生效的记录）。不允许空范围，每个就诊都必须属于该患者
15	// （跨患者就诊会被拒绝），类别必须合法。时间窗为半开区间
16	// [startsAt, expiresAt)：开始时刻即生效，到截止时刻立即失效；
17	// 开始不早于截止时间（相等也算）一律拒绝。患者档案停用后不能新建授权。
18	// 授权与审计事件在同一次原子落盘中保留。
19	func (s *Store) Grant(actor Actor, patientID ID, receiverID string, scopes []Scope, startsAt, expiresAt time.Time) (Authorization, error) {
20		return s.GrantSelective(actor, patientID, receiverID, scopes, nil, startsAt, expiresAt)
21	}
22	
23	// GrantSelective 由内部使用者为一名接收方建立针对某患者的读取授权，
24	// 整类范围（scopes）与限定记录范围（selections）可以并存，同一条授权
25	// 可以包含多个就诊、类别。
26	//
27	// scopes 的每项按整类授权：覆盖该就诊+类别下全部已生效记录，并自然
28	// 包含授权后新增生效的记录；selections 的每项明确选出一条已生效记录，
29	// 被选记录更正后授权覆盖它的当前版本，但同一就诊同一类别的其他记录、
30	// 后来新增并生效的记录都不会自动进入限定范围。重复选择同一记录只算一次。
31	//
32	// scopes 与 selections 不能同时为空：空选择不代表整类授权。scope 中的
33	// 就诊必须存在且属于该患者，类别必须合法。每条 selection 都必须显式
34	// 声明记录所属的就诊与类别，且：记录不存在返回 ErrNotFound；记录属于
35	// 其他患者返回 ErrMismatchedPatient；空选择、空白标识、选择了尚未生效
36	// 的草稿、记录与声明的就诊或类别不符返回 ErrInvalidArgument。任一选择
37	// 不合法就拒绝整条授权：不保存合法部分，也不新增审计。
38	//
39	// 时间窗、停用档案与审计规则与 [Store.Grant] 相同。
40	func (s *Store) GrantSelective(actor Actor, patientID ID, receiverID string, scopes []Scope, selections []RecordSelection, startsAt, expiresAt time.Time) (Authorization, error) {
41		if !actor.valid() || !actor.IsInternal() {
42			return Authorization{}, ErrAccessDenied
43		}
44		if patientID == "" {
45			return Authorization{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
46		}
47		if strings.TrimSpace(receiverID) == "" {
48			return Authorization{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
49		}
50		if len(scopes) == 0 && len(selections) == 0 {
51			return Authorization{}, fmt.Errorf("%w: authorization scope must not be empty", ErrInvalidArgument)
52		}
53		for _, sc := range scopes {
54			if sc.EncounterID == "" {
55				return Authorization{}, fmt.Errorf("%w: scope encounter id is required", ErrInvalidArgument)
56			}
57			if !validCategory(sc.Category) {
58				return Authorization{}, fmt.Errorf("%w: scope category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
59			}
60		}
61		for _, sel := range selections {
62			if strings.TrimSpace(sel.RecordID) == "" {
63				return Authorization{}, fmt.Errorf("%w: selection record id is required", ErrInvalidArgument)
64			}
65			if strings.TrimSpace(sel.EncounterID) == "" {
66				return Authorization{}, fmt.Errorf("%w: selection encounter id is required", ErrInvalidArgument)
67			}
68			if !validCategory(sel.Category) {
69				return Authorization{}, fmt.Errorf("%w: selection category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
70			}
71		}
72		if !startsAt.Before(expiresAt) {
73			return Authorization{}, fmt.Errorf("%w: starts-at must be strictly before expires-at", ErrInvalidArgument)
74		}
75	
76		var result Authorization
77		err := s.mutate(func(snap *snapshot) error {
78			if _, err := requireActivePatient(snap, patientID); err != nil {
79				return err
80			}
81	
82			// 去重并逐项校验整类范围：引用的就诊必须存在且属于该患者。
83			seenScope := map[Scope]bool{}
84			cleanedScopes := make([]Scope, 0, len(scopes))
85			for _, sc := range scopes {
86				if _, err := requireEncounter(snap, patientID, sc.EncounterID); err != nil {
87					return err
88				}
89				if seenScope[sc] {
90					continue
91				}
92				seenScope[sc] = true
93				cleanedScopes = append(cleanedScopes, sc)
94			}
95			sort.Slice(cleanedScopes, func(i, j int) bool {
96				if cleanedScopes[i].EncounterID != cleanedScopes[j].EncounterID {
97					return cleanedScopes[i].EncounterID < cleanedScopes[j].EncounterID
98				}
99				return cleanedScopes[i].Category < cleanedScopes[j].Category
100			})
101	
102			// 逐项校验限定范围：就诊必须属于该患者；记录必须存在、属于该患者、
103			// 已生效，且实际就诊与类别与声明一致。任一不合法即整体拒绝。
104			seenRecord := map[ID]bool{}
105			cleanedSelections := make([]RecordSelection, 0, len(selections))
106			for _, sel := range selections {
107				if _, err := requireEncounter(snap, patientID, sel.EncounterID); err != nil {
108					return err
109				}
110				r := snap.Records[sel.RecordID]
111				if r == nil {
112					return fmt.Errorf("%w: record %q", ErrNotFound, sel.RecordID)
113				}
114				if r.PatientID != patientID {
115					return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
116						ErrMismatchedPatient, sel.RecordID, r.PatientID, patientID)
117				}
118				if r.CurrentVersionID == "" {
119					return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
120						ErrInvalidArgument, sel.RecordID)
121				}
122				if r.EncounterID != sel.EncounterID || r.Category != sel.Category {
123					return fmt.Errorf("%w: record %q belongs to encounter %q category %q, not declared encounter %q category %q",
124						ErrInvalidArgument, sel.RecordID, r.EncounterID, r.Category, sel.EncounterID, sel.Category)
125				}
126				if seenRecord[sel.RecordID] {
127					// 重复选择同一记录只算一次。
128					continue
129				}
130				seenRecord[sel.RecordID] = true
131				cleanedSelections = append(cleanedSelections, sel)
132			}
133			sort.Slice(cleanedSelections, func(i, j int) bool {
134				return cleanedSelections[i].RecordID < cleanedSelections[j].RecordID
135			})
136	
137			now := s.now()
138			a := &Authorization{
139				ID:         newID("auth"),
140				PatientID:  patientID,
141				ReceiverID: receiverID,
142				Scopes:     cleanedScopes,
143				Selections: cleanedSelections,
144				StartsAt:   startsAt.UTC(),
145				ExpiresAt:  expiresAt.UTC(),
146				CreatedAt:  now,
147			}
148			snap.Authorizations[a.ID] = a
149			s.addAudit(snap, patientID, actor, ActionGranted, "authorization", a.ID, now)
150			result = cloneAuthorizationValue(a)
151			return nil
152		})
153		return result, err
154	}
155	
156	// Revoke 提前撤回授权。撤回在当前时间生效；此后该授权不再覆盖任何读取。
157	// 重复撤回返回成功且不产生额外变化（不新增审计事件、不改写撤回时间与操作
158	// 身份），与“停用”语义一致。确认只依据正式保存的撤回结果：即使本地保存
159	// 条件当前暂时不可用，合法的重复撤回也成功返回已有结果，不再尝试写盘；
160	// 但授权尚未撤回时若保存失败，仍明确返回保存错误。撤回其他患者的授权 ID
161	// 会得到 ErrMismatchedPatient/ErrNotFound（与授权是否已撤回无关）。
162	func (s *Store) Revoke(actor Actor, patientID, authorizationID ID) error {
163		if !actor.valid() || !actor.IsInternal() {
164			return ErrAccessDenied
165		}
166		return s.mutate(func(snap *snapshot) error {
167			a := snap.Authorizations[authorizationID]
168			if a == nil {
169				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
170			}
171			if a.PatientID != patientID {
172				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
173					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
174			}
175			if a.RevokedAt != nil {
176				// 幂等：正式保存的授权已经撤回。确认已有结果即可——保持首次撤回
177				// 的时间与操作身份、原接收方/范围/有效期，不生成额外变化或事件，
178				// 也不落盘：重复确认不依赖当前能否写入本地数据，任何内部使用者
179				// 的合法确认都得到同一结果，且不能把撤回时间更新到本次调用时刻。
180				return errUnchanged
181			}
182			now := s.now()
183			a.RevokedAt = &now
184			s.addAudit(snap, patientID, actor, ActionRevoked, "authorization", a.ID, now)
185			return nil
186		})
187	}
188	
189	// GetAuthorization 返回单个授权。仅供内部使用者。
190	func (s *Store) GetAuthorization(actor Actor, patientID, authorizationID ID) (Authorization, error) {
191		if !actor.valid() || !actor.IsInternal() {
192			return Authorization{}, ErrAccessDenied
193		}
194		var result Authorization
195		err := s.view(func(snap *snapshot) error {
196			a := snap.Authorizations[authorizationID]
197			if a == nil {
198				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
199			}
200			if a.PatientID != patientID {
201				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
202					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
203			}
204			result = cloneAuthorizationValue(a)
205			return nil
206		})
207		return result, err
208	}
209	
210	// ListAuthorizations 列出某患者（可选：某接收方）的全部授权，含已撤回者。
211	// 仅供内部使用者。
212	func (s *Store) ListAuthorizations(actor Actor, patientID ID, receiverID string) ([]Authorization, error) {
213		if !actor.valid() || !actor.IsInternal() {
214			return nil, ErrAccessDenied
215		}
216		var result []Authorization
217		err := s.view(func(snap *snapshot) error {
218			if _, err := requirePatient(snap, patientID); err != nil {
219				return err
220			}
221			for _, a := range snap.Authorizations {
222				if a.PatientID != patientID {
223					continue
224				}
225				if receiverID != "" && a.ReceiverID != receiverID {
226					continue
227				}
228				result = append(result, cloneAuthorizationValue(a))
229			}
230			sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
231			return nil
232		})
233		return result, err
234	}
235	
236	// Read 供接收方按自己的身份读取某次就诊下某个类别（诊断/医嘱）的内容。
237	//
238	// 结果是该接收方在“本次读取时间”所有当前有效授权允许记录的合集。“本次读取
239	// 时间”指真正开始核对权限的时刻：请求发出后若因等待同一存储上的其他操作而
240	// 排队，以等待结束、开始核对时的同一时刻统一判断本次涉及的各条授权是否有效，
241	// 等待本身不会延长或推迟授权的有效期。每条记录
242	// 只出现一次并按记录标识稳定排序：授权必须属于该接收方与该患者、已开始、
243	// 未到期且未撤回；整类范围（Scope）允许该就诊+类别下的全部已生效记录
244	// （含授权后才生效者），限定范围（RecordSelection）仅允许明确选中的记录。
245	// 同一条记录被多条授权（含整类与限定重叠）允许也只出现一次；被选记录被
246	// 更正后读取其当前生效版本。看不到草稿、旧版本或更正原因。
247	//
248	// 若不存在任何覆盖所请求就诊+类别的有效授权（全部尚未开始、已到期或已
249	// 撤回），或患者档案已停用，返回 ErrAccessDenied：结果中不含任何未授权
250	// 记录的标识、数量或内容。撤回整类授权后，只剩其他有效授权明确允许的记录。
251	func (s *Store) Read(actor Actor, patientID, encounterID ID, category string) (ReadResult, error) {
252		if !actor.valid() || actor.Kind != "receiver" {
253			return ReadResult{}, ErrAccessDenied
254		}
255		if patientID == "" || encounterID == "" {
256			return ReadResult{}, fmt.Errorf("%w: patient and encounter ids are required", ErrInvalidArgument)
257		}
258		if !validCategory(category) {
259			return ReadResult{}, fmt.Errorf("%w: category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
260		}
261	
262		var out ReadResult
263		err := s.view(func(snap *snapshot) error {
264			// 查阅时刻在进入临界区、真正开始核对权限时才取样：请求发出后若因
265			// 等待其他操作而排队，等待时间不能延长或推迟授权的有效判断——
266			// 本次读取涉及的所有授权统一按这同一时刻判断是否有效。
267			now := s.now()
268			// 合并该患者、该接收方所有当前有效授权的覆盖：整类范围与限定范围的
269			// 解释与创建交换共用同一套判定（grantCoverage），不在这里另写一份。
270			// 不提前区分“对象不存在/属于他人”与“无授权”，统一返回拒绝，从而不
271			// 向接收方泄露患者或就诊是否存在。
272			coverage := newGrantCoverage()
273			patientDeactivated := false
274			if p := snap.Patients[patientID]; p != nil {
275				patientDeactivated = p.Deactivated
276			}
277			for _, a := range snap.Authorizations {
278				if a.PatientID != patientID || a.ReceiverID != actor.ID {
279					continue
280				}
281				if !a.ActiveAt(now) {
282					// 未开始、已到期或已撤回的授权不参与覆盖。
283					continue
284				}
285				coverage.add(a)
286			}
287			if patientDeactivated || !coverage.coversRequest(encounterID, category) {
288				// 无授权、未开始、已到期、已撤回或档案停用：明确拒绝，
289				// 结果中不含任何受保护内容。整类授权覆盖该就诊+类别但其中暂时
290				// 没有生效记录时，coversRequest 仍为真，随后成功返回空集合，
291				// 不会把“有授权无记录”误判成拒绝。
292				return ErrAccessDenied
293			}
294	
295			// 能被授权覆盖的就诊必然属于该患者（Grant 时已校验），
296			// 此处再确认一次以防任何不一致状态。
297			e := snap.Encounters[encounterID]
298			if e == nil || e.PatientID != patientID {
299				return ErrAccessDenied
300			}
301	
302			out.EncounterID = encounterID
303			out.Category = category
304			var recs []EffectiveRecord
305			for _, r := range snap.Records {
306				if r.EncounterID != encounterID || r.Category != category || r.PatientID != patientID {
307					continue
308				}
309				// 整类范围覆盖全部（含授权后才生效者）；限定范围只覆盖明确选中
310				// 的记录，同类其他记录与后来新增记录不被覆盖。多条授权、整类与
311				// 限定重叠时同一条记录只出现一次。
312				if !coverage.coversRecord(r) {
313					continue
314				}
315				if eff, ok := currentEffective(snap, r); ok {
316					recs = append(recs, eff)
317				}
318				// 仅有草稿、尚无生效版本的记录天然不出现；
319				// 限定授权选中的记录在授权后也不会退回草稿状态。
320			}
321			sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
322			out.Records = recs
323			return nil
324		})
325		return out, err
326	}
327	
328	// cloneAuthorizationValue 返回授权的深拷贝：整类范围、限定范围与撤回时间
329	// 都与库内保存的对象各自独立。返回给调用方的授权只是本次操作得到的信息；
330	// 调用方在本地修改它（改范围、换记录标识、改撤回时间）不能改变库内正式
331	// 保存的授权，从同一授权取得的多份结果也互不影响。
332	func cloneAuthorizationValue(a *Authorization) Authorization {
333		out := *a
334		out.Scopes = append([]Scope(nil), a.Scopes...)
335		out.Selections = append([]RecordSelection(nil), a.Selections...)
336		if a.RevokedAt != nil {
337			t := *a.RevokedAt
338			out.RevokedAt = &t
339		}
340		return out
341	}
342

